//! Context X-Ray ASCII diagnostic dashboard renderer and economics calculator (`FR-12`).

use serde::{Deserialize, Serialize};

/// Commercial model pricing tiers for input tokens (cost per 1M tokens in USD).
pub const GPT4O_INPUT_COST_PER_1M: f64 = 2.50;
pub const CLAUDE_SONNET_INPUT_COST_PER_1M: f64 = 3.00;

/// Complete diagnostic report generated by Context X-Ray analysis.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct XRayReport {
    pub input_bytes: usize,
    pub output_bytes: usize,
    pub original_tokens: usize,
    pub compressed_tokens: usize,
    pub token_reduction_pct: f32,
    pub tier1_latency_ns: u64,
    pub tier1_ns_per_byte: f64,
    pub tier2_latency_ns: u64,
    pub tier2_ns_per_byte: f64,
    pub tier3_latency_ns: u64,
    pub tier3_ns_per_byte: f64,
    pub total_latency_ns: u64,
    pub total_ns_per_byte: f64,
    pub evaluated_windows: usize,
    pub max_threat_score: f32,
    pub threat_threshold: f32,
    pub threat_verdict: String,
    pub is_blocked: bool,
    pub redacted_credentials: usize,
    pub vaulted_pii_tokens: usize,
    pub syntax_locks_preserved: bool,
    pub fail_open_triggered: bool,
    pub gpt4o_savings_per_1m: f64,
    pub claude_sonnet_savings_per_1m: f64,
}

impl XRayReport {
    /// Constructs an [`XRayReport`] from measured telemetry.
    #[must_use]
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        input_bytes: usize,
        output_bytes: usize,
        original_tokens: usize,
        compressed_tokens: usize,
        tier1_latency_ns: u64,
        tier2_latency_ns: u64,
        tier3_latency_ns: u64,
        evaluated_windows: usize,
        max_threat_score: f32,
        threat_threshold: f32,
        threat_verdict: String,
        is_blocked: bool,
        redacted_credentials: usize,
        vaulted_pii_tokens: usize,
        syntax_locks_preserved: bool,
        fail_open_triggered: bool,
    ) -> Self {
        let total_latency_ns = tier1_latency_ns
            .saturating_add(tier2_latency_ns)
            .saturating_add(tier3_latency_ns);
        let tier1_ns_per_byte = if input_bytes > 0 {
            (tier1_latency_ns as f64) / (input_bytes as f64)
        } else {
            0.0
        };
        let tier2_ns_per_byte = if input_bytes > 0 {
            (tier2_latency_ns as f64) / (input_bytes as f64)
        } else {
            0.0
        };
        let tier3_ns_per_byte = if input_bytes > 0 {
            (tier3_latency_ns as f64) / (input_bytes as f64)
        } else {
            0.0
        };
        let total_ns_per_byte = if input_bytes > 0 {
            (total_latency_ns as f64) / (input_bytes as f64)
        } else {
            0.0
        };

        let token_reduction_pct = if original_tokens > 0 && compressed_tokens < original_tokens {
            (((original_tokens - compressed_tokens) as f32) / (original_tokens as f32)) * 100.0
        } else {
            0.0
        };

        let reduction_factor = (token_reduction_pct as f64) / 100.0;
        let gpt4o_savings_per_1m = reduction_factor * GPT4O_INPUT_COST_PER_1M;
        let claude_sonnet_savings_per_1m = reduction_factor * CLAUDE_SONNET_INPUT_COST_PER_1M;

        Self {
            input_bytes,
            output_bytes,
            original_tokens,
            compressed_tokens,
            token_reduction_pct,
            tier1_latency_ns,
            tier1_ns_per_byte,
            tier2_latency_ns,
            tier2_ns_per_byte,
            tier3_latency_ns,
            tier3_ns_per_byte,
            total_latency_ns,
            total_ns_per_byte,
            evaluated_windows,
            max_threat_score,
            threat_threshold,
            threat_verdict,
            is_blocked,
            redacted_credentials,
            vaulted_pii_tokens,
            syntax_locks_preserved,
            fail_open_triggered,
            gpt4o_savings_per_1m,
            claude_sonnet_savings_per_1m,
        }
    }

    /// Formats the diagnostic report into an ASCII terminal dashboard.
    #[must_use]
    pub fn render_ascii_dashboard(&self) -> String {
        let lock_status = if self.syntax_locks_preserved {
            "100% PASSED (Fail-Open Guard Active)"
        } else {
            "FAILED (Syntax Corrupted)"
        };

        let fail_open_note = if self.fail_open_triggered {
            " [TRIGGERED: Recovered uncompressed content]"
        } else {
            ""
        };

        format!(
            concat!(
                "================================================================================\n",
                "                          CONTEXT SANITIZER X-RAY\n",
                "================================================================================\n",
                " Latency Breakdown:\n",
                "   Tier 1 (Guard + Vault) : {:>10} ns   ({:>6.1} ns/byte)\n",
                "   Tier 2 (Compression)   : {:>10} ns   ({:>6.1} ns/byte)\n",
                "   Tier 3 (ML Gatekeeper) : {:>10} ns   ({:>6.1} ns/byte)\n",
                "   Total Pipeline Elapsed : {:>10} ns   ({:>6.1} ns/byte)\n",
                "--------------------------------------------------------------------------------\n",
                " Threat Gatekeeper (Tier 3):\n",
                "   Gatekeeper Verdict     : {:<10}\n",
                "   Max Threat Score       : {:>10.4}   (threshold: {:.2})\n",
                "   Evaluated Windows      : {:>10}\n",
                "--------------------------------------------------------------------------------\n",
                " Token Metrics:\n",
                "   Original Tokens        : {:>10}\n",
                "   Compressed Tokens      : {:>10}\n",
                "   Token Reduction        : {:>9.1}%\n",
                "--------------------------------------------------------------------------------\n",
                " Security & Integrity:\n",
                "   Redacted Credentials   : {:>10}\n",
                "   Vaulted PII Tokens     : {:>10}\n",
                "   Syntax Lock Status     : {}{}\n",
                "--------------------------------------------------------------------------------\n",
                " Economic Impact (per 1M input tokens):\n",
                "   GPT-4o Savings         : ${:.2} / 1M tokens ($2.50 base)\n",
                "   Claude 3.5 Sonnet      : ${:.2} / 1M tokens ($3.00 base)\n",
                "================================================================================\n"
            ),
            self.tier1_latency_ns,
            self.tier1_ns_per_byte,
            self.tier2_latency_ns,
            self.tier2_ns_per_byte,
            self.tier3_latency_ns,
            self.tier3_ns_per_byte,
            self.total_latency_ns,
            self.total_ns_per_byte,
            self.threat_verdict,
            self.max_threat_score,
            self.threat_threshold,
            self.evaluated_windows,
            self.original_tokens,
            self.compressed_tokens,
            self.token_reduction_pct,
            self.redacted_credentials,
            self.vaulted_pii_tokens,
            lock_status,
            fail_open_note,
            self.gpt4o_savings_per_1m,
            self.claude_sonnet_savings_per_1m
        )
    }
}
